    year,
    temaPersonalizado: temaDoMes,
    temaModo: "mes_auto"
  });
  const gd = (genRes.body && genRes.body.data) || {};
  texto = `������ *Devocional do Dia:* ${gd.titulo || "Palavra do Dia"}\n\n📖 *Texto Base:* ${gd.versiculo_ref || gd.passagem || "Escrituras Sagradas"}\n\n${gd.versiculo_texto ? `"${gd.versiculo_texto}"\n\n` : ""}${gd.reflexao || gd.texto || ""}\n\n${gd.oracao ? `🙏 *Oração:*\n_${gd.oracao}_\n\n` : ""}Amém! Que Deus abençoe sua jornada. 🙌`;
}


function splitTelegramMessage(text, maxLen = 3900) {
  if (!text || typeof text !== 'string') return [text || ''];
  if (text.length <= maxLen) return [text];
  const chunks = [];
  let remaining = text;
  while (remaining.length > 0) {
    if (remaining.length <= maxLen) {
      chunks.push(remaining);
      break;
    }
    let splitIdx = remaining.lastIndexOf('\n\n', maxLen);
    if (splitIdx < maxLen * 0.4) {
      splitIdx = remaining.lastIndexOf('\n', maxLen);
    }
    if (splitIdx < maxLen * 0.4) {
      splitIdx = remaining.lastIndexOf('. ', maxLen);
      if (splitIdx !== -1) splitIdx += 1;
    }
    if (splitIdx < maxLen * 0.3) {
      splitIdx = remaining.lastIndexOf(' ', maxLen);
    }
    if (splitIdx <= 0) {
      splitIdx = maxLen;
    }
    const chunk = remaining.substring(0, splitIdx).trim();
    if (chunk) chunks.push(chunk);
    remaining = remaining.substring(splitIdx).trim();
  }
  return chunks.length ? chunks : [text];
}


// ── GERAÇÃO E ENVIO DE ÁUDIO NARRADO (OpenAI TTS - Voz Onyx) ────────────
const openaiKey = String($env.OPENAI_API_KEY || "").trim();
const tgToken = String($env.TELEGRAM_BOT_TOKEN || "").trim();

if (openaiKey && tgToken && targetChatId) {
  try {
    const textoAudio = texto
      .replace(/[*_#`~]/g, '')
      .replace(/[🌅📖🙏🙌🕊️👑🌙💎🗣️]/g, '')
      .replace(/\n{2,}/g, '. ')
      .trim()
      .slice(0, 4000);

    const ttsRes = await fetch("https://api.openai.com/v1/audio/speech", {
      method: "POST",
      headers: {
        "Authorization": "Bearer " + openaiKey,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        model: "tts-1",
        voice: "onyx",
        input: textoAudio
      })
    });

    if (ttsRes.ok) {
      const audioBuf = await ttsRes.arrayBuffer();
      const form = new FormData();
      form.append("chat_id", targetChatId);
      form.append("voice", new Blob([audioBuf], { type: "audio/ogg" }), "devocional.ogg");
      form.append("caption", "🎧 *Devocional em Áudio* — Ouça a reflexão de hoje.");
      form.append("parse_mode", "Markdown");

