        method: "POST",
        body: form
      });
    }
  } catch (errAudio) {
    // Se o áudio falhar, o envio do texto em chunks prossegue sem travar
  }
}

const chunks = splitTelegramMessage(texto, 3900);
return chunks.map(c => ({
  json: {
    chatId: targetChatId,
    text: c
  }
}));

